-- 자동 생성: scripts/gen-seed-sql.mjs (src/data/materialSeed.ts)
-- 파이썬 1~4주차 8차시 — 학생용 내용 / 교사용 수업안 / 정답 코드가 분리되어 들어갑니다.
insert into public.materials
  (seed_key, kind, title, track, week, session, summary, student_content, teacher_guide, answer_code, ai_tip, link_url, code_lang, published, sort_no)
values
  ('py-w01-s1', 'theory', '변수 하나로 내 소개 카드 만들기 (2시간)', 'python', 1, 1,
   '변수·input·print·f-string으로 내 소개 카드를 만들고, 값을 바꾸면 카드도 바뀌는 걸 확인합니다.', $jc${"goal":"이름·나이·좋아하는 것·오늘 기분을 넣으면 내 소개 카드가 출력되고, 값을 바꾸면 카드도 따라 바뀐다","preview":"이름: 지훈\n나이: 14\n좋아하는 것: 코딩\n오늘 기분: good\n======================\n      내 소개 카드\n======================\n이름        : 지훈\n나이        : 14\n좋아하는 것 : 코딩\n오늘 기분   : good\n======================","words":["변수","input()","print()","f-string"],"conceptTitle":"변수는 이름표가 붙은 상자","concept":[{"code":"name = \"지훈\"","mean":"name이라는 상자에 \"지훈\"을 넣는다 (= 는 넣기)"},{"code":"age = 14","mean":"age 상자에 숫자 14를 넣는다"},{"code":"print(name)","mean":"상자에서 꺼내 화면에 보여 준다"},{"code":"name = \"수민\"","mean":"같은 상자에 새 값을 넣으면 예전 값은 사라진다"},{"code":"input(\"이름: \")","mean":"물음표를 띄우고 학생이 친 글자를 문자열로 받아 온다"},{"code":"f\"이름: {name}\"","mean":"틀(f) 안의 중괄호 자리에 상자 속 값을 끼워 넣는다"},{"code":"print(\"=\" * 22)","mean":"글자에 숫자를 곱하면 그만큼 반복된다"}],"predict":{"code":"a = 10\nb = \"10\"\nprint(a + a)\nprint(b + b)","answer":"20 / 1010 — b는 글자라서 이어 붙습니다"},"steps":[{"title":"1단계 — 상자 4개 만들기 (값을 물어보게)","code":"name = input(\"이름: \")\nage = input(\"나이: \")\nhobby = input(\"좋아하는 것: \")\nmood = input(\"오늘 기분: \")","note":"input()은 학생이 엔터를 칠 때까지 기다립니다. 4줄이면 질문 4개가 차례대로 나옵니다."},{"title":"2단계 — 테두리 먼저 찍기","code":"print(\"=\" * 22)\nprint(\"      내 소개 카드\")\nprint(\"=\" * 22)"},{"title":"3단계 — f-string으로 값 끼우기","code":"print(f\"이름        : {name}\")\nprint(f\"나이        : {age}\")\nprint(f\"좋아하는 것 : {hobby}\")\nprint(f\"오늘 기분   : {mood}\")","note":"문자열 앞에 f를 붙이고, {} 안에 변수 이름을 씁니다. 콜론 위치를 줄마다 똑같이 맞추면 표처럼 보입니다."},{"title":"4단계 — 닫는 줄까지","code":"print(\"=\" * 22)"},{"title":"5단계 — 저장하고 내 값으로 3번 실행","note":"파일 이름: 1주_내카드_내이름.py · 이름·나이·좋아하는 것·기분을 바꿔서 3번 실행하면 오늘 카드 완성입니다."}],"builds":[{"label":"기초","title":"① 인사 한 줄 — 변수 하나만","intro":"오늘 배우는 것 중 제일 작은 성공부터. 상자 1개, print 1줄.","steps":[{"title":"코드","code":"name = input(\"이름: \")\nprint(f\"안녕하세요, {name}님!\")"}],"out":"이름: 지훈\n안녕하세요, 지훈님!"},{"label":"변형","title":"② 상자를 3개로 늘려 카드 만들기","intro":"①의 코드에서 줄만 늘리면 됩니다. 이름·나이·좋아하는 것.","steps":[{"title":"코드","code":"name = input(\"이름: \")\nage = input(\"나이: \")\nhobby = input(\"좋아하는 것: \")\n\nprint(\"--- 내 소개 ---\")\nprint(f\"이름: {name}\")\nprint(f\"나이: {age}\")\nprint(f\"좋아하는 것: {hobby}\")\nprint(\"---------------\")"}],"out":"이름: 수민\n나이: 13\n좋아하는 것: 농구\n--- 내 소개 ---\n이름: 수민\n나이: 13\n좋아하는 것: 농구\n---------------"},{"label":"실전","title":"③ 오늘 기분까지 넣고 표처럼 줄 맞추기","intro":"이게 오늘의 완성본입니다. 콜론(:) 위치를 네 줄 모두 똑같이 맞추는 게 포인트.","steps":[{"title":"코드","code":"name = input(\"이름: \")\nage = input(\"나이: \")\nhobby = input(\"좋아하는 것: \")\nmood = input(\"오늘 기분: \")\n\nprint(\"=\" * 22)\nprint(\"      내 소개 카드\")\nprint(\"=\" * 22)\nprint(f\"이름        : {name}\")\nprint(f\"나이        : {age}\")\nprint(f\"좋아하는 것 : {hobby}\")\nprint(f\"오늘 기분   : {mood}\")\nprint(\"=\" * 22)"},{"title":"확인","note":"네 줄의 콜론이 세로로 나란히 서면 성공. 한 줄만 어긋나면 그 줄의 띄어쓰기 수를 세어 보세요."}],"out":"이름: 지훈\n나이: 14\n좋아하는 것: 코딩\n오늘 기분: good\n======================\n      내 소개 카드\n======================\n이름        : 지훈\n나이        : 14\n좋아하는 것 : 코딩\n오늘 기분   : good\n======================"}],"practice":[{"title":"실습 1 — 내 이름과 한 줄 소개","prompt":"name에 내 이름을 직접 넣고(입력 말고 코드에), 한 줄 소개를 출력하세요.","starter":"name = \"여기에 내 이름\"\nprint(f\"저는 {name}입니다.\")\nprint(\"______\")  # 내 한 줄 소개로 바꾸기","expect":"저는 지훈입니다.\n코딩을 좋아하는 중학생입니다."},{"title":"실습 2 — 질문 2개, 문장 1개","prompt":"이름과 오늘 기분을 물어보고 한 문장으로 이어서 출력하세요.","starter":"name = input(\"이름: \")\nmood = input(\"오늘 기분: \")\n# 여기에 print 한 줄을 채우세요","expect":"이름: 수민\n오늘 기분: 신남\n수민님은 오늘 신남한 하루였군요!","hint":"f\"___님은 오늘 ___한 하루였군요!\" 안에 {name} 과 {mood} 를 넣어 보세요."},{"title":"실습 3 — f가 있을 때와 없을 때","prompt":"두 줄을 실행해 결과가 어떻게 다른지 확인하고, 왜 그런지 한 줄로 적으세요.","starter":"name = \"지훈\"\nprint(\"안녕 {name}\")\nprint(f\"안녕 {name}\")","expect":"안녕 {name}\n안녕 지훈","hint":"f가 없으면 중괄호도 그냥 글자로 취급됩니다."},{"title":"실습 4 — 값을 바꿔 3번 실행","prompt":"내 값으로 카드를 3번 실행하며, 카드 내용이 따라 바뀌는지 확인하세요. 마지막 실행 결과를 선생님께 보여 주세요.","expect":"같은 코드인데 입력한 값에 따라 카드 내용이 매번 달라진다."}],"mistakes":[{"symptom":"SyntaxError: unterminated string literal","cause":"따옴표 한쪽을 닫지 않았다"},{"symptom":"화면에 {name}이 그대로 나온다","cause":"문자열 앞 f를 빼먹었다"},{"symptom":"NameError: name 'nmae' is not defined","cause":"변수 이름 철자가 다르다(대소문자 포함)"},{"symptom":"질문은 나오는데 아무것도 안 나온다","cause":"input()으로 받기만 하고 print()를 안 썼다"},{"symptom":"카드가 두 번 겹쳐 나온다","cause":"실행 버튼을 두 번 눌렀거나 print를 두 번 썼다"}],"hints":["빨간 글씨의 마지막 줄과 가리키는 줄 번호를 먼저 읽어요.","중괄호가 글자로 보이면 f를 잊은 거예요.","컴퓨터는 Name과 name을 다른 이름으로 봐요.","값을 넣었는데 안 나오면, print() 안에 그 상자 이름을 썼는지 확인해요."],"selfcheck":["내 이름·나이·좋아하는 것·기분으로 값 4개를 바꿨다","f를 붙인 줄과 안 붙인 줄의 차이를 설명할 수 있다","콜론(:) 위치를 네 줄 모두 맞춰 표처럼 만들었다","오류가 났을 때 빨간 글씨 마지막 줄을 읽었다","1주_내카드_내이름.py 로 저장했다"],"note":"input()이 받는 건 언제나 글자예요. 14라고 쳐도 \"14\"라는 글자입니다. 계산은 다음 시간(2회차)에 붙입니다."}$jc$::jsonb, $jt${"demo":"'오늘 2시간 끝나면 이게 뜹니다. 이름 치고, 나이 치고, 좋아하는 것 치면 내 카드가 나와요. 오늘 배우는 건 딱 하나, 변수입니다. 나머지 두 시간은 손으로 익히는 시간이에요.'","analogy":"상자에 물건을 넣고 이름표를 붙인다 → name = \"지훈\". print는 뚜껑을 열어 보여 주는 것, input은 빈 상자를 내밀고 글자를 받아 오는 것, f-string은 카드 틀에 이름표를 끼우는 것.","timeline":[{"min":"0~10","title":"도입 — 완성 화면 먼저","detail":"완성 카드를 화면에 띄우고 \"2시간 뒤 이게 여러분 화면에 뜹니다\"로 시작. 파이썬 실행·저장 폴더 확인(새 파일 1주_내카드_이름.py). 첫 수업이면 저장 위치를 다 같이 정합니다."},{"min":"10~25","title":"개념 — 변수 상자 1개","detail":"판서로 상자 그림 → name = \"지훈\" → print(name) → name = \"수민\"으로 값이 바뀌는 것까지. 학생은 그대로 따라 치며 print 3번 실행. 개념은 하나만: \"변수는 이름표 붙은 상자\"."},{"min":"25~45","title":"따라 만들기 ① 기초","detail":"인사 한 줄(상자 1개 + print 1줄). 전원 성공 확인 — 손 든 학생 수를 세고, 안 든 학생은 따옴표·괄호부터 점검. 성공 경험을 먼저 만들어 둡니다."},{"min":"45~70","title":"따라 만들기 ② 변형","detail":"상자를 3개로 늘려 카드 만들기. 여기서 input을 받기만 하고 print를 안 쓰는 학생이 반드시 나옵니다 — \"받기 / 보여주기\" 두 동작을 판서로 분리."},{"min":"70~90","title":"따라 만들기 ③ 실전","detail":"오늘 기분까지 4개 + 테두리 + 콜론 정렬. f를 일부러 빼고 실행해 {name}이 그대로 나오는 장면을 다 같이 본 뒤 f를 넣습니다. 마지막 5분은 내 값으로 3번 실행."},{"min":"90~105","title":"미니 실습 1~3","detail":"각자 진행. 1번(이름 출력)은 전원, 2번(질문 2개 → 문장 1개)은 대부분, 3번(f 유무 비교)은 설명까지. 빨리 끝난 학생은 4번(값 바꿔 3번 실행)과 옆 친구 점검."},{"min":"105~115","title":"AI 틈틈이 + 정리","detail":"카드 문구 3안을 AI에게 받아 1개 고르기(코드는 받지 않기). 다 된 학생은 \"내 설명에서 틀린 부분만\" 검사. 5분 남으면 selfcheck 5개를 소리 내어 확인."},{"min":"115~120","title":"저장·발표·예고","detail":"저장 확인 → 1분 발표(내 카드에서 바꾼 것 1개) → 다음 시간 예고: \"오늘 받은 나이는 사실 글자입니다. 다음 시간에 계산을 붙이며 그걸 직접 터뜨려 봅니다.\""},{"min":"여유 시","title":"+α 확장","detail":"카드를 두 장 만들어 친구 것을 입력해 보게 하거나, print(\"=\" * 40) 폭을 바꿔 보게 합니다. 새 문법은 절대 추가하지 않습니다."}],"board":[{"say":"컴퓨터는 기억을 어디에 둘까요?","write":"[    ] 빈 상자 1개"},{"say":"이름표를 붙여 봅시다","write":"상자 위에 name"},{"say":"값을 넣습니다 (= 는 넣기)","write":"상자 안에 \"지훈\""},{"say":"꺼내서 보여 주기","write":"print(name) → 지훈"},{"say":"학생이 친 글자를 받아 오려면?","write":"input(\"이름: \") + 화살표로 상자에 연결"},{"say":"f-string은 카드 틀에 끼우기","write":"f\"이름: {name}\" → 중괄호만 색 다르게"},{"say":"테두리는 곱하기로","write":"print(\"=\" * 22)"},{"say":"함정","write":"a = 10 / b = \"10\" → a+a=20, b+b=1010"},{"say":"두 동작을 헷갈리지 않기","write":"받기(input) / 보여주기(print)"}],"ai":[{"when":"만들기 시작 3분 (35분경)","what":"카드 문구 아이디어 3개","prompt":"중학생 소개 카드에 들어갈 짧은 문구 3개만 제안해줘. 코드는 주지 마.","rule":"문구만 받고 코드는 받지 않는다 — 고르는 건 학생"},{"when":"정리 5분 (108분경)","what":"내 설명 검사","prompt":"내가 쓴 코드 설명: 'name은 이름을 넣는 상자고, input은 화면에 보여주는 거야' — 이 설명에서 틀린 부분만 짚어줘.","rule":"AI가 쓴 코드를 붙여 넣으면 안 됨(내 것만 검사)"}],"errors":[{"symptom":"SyntaxError","cause":"따옴표·괄호 짝이 안 맞음","coach":"빨간 줄이 가리키는 줄 번호부터 봐요. 그 줄 위아래만 보면 90% 나옵니다."},{"symptom":"{name} 그대로 출력","cause":"f 누락","coach":"중괄호가 글자로 보이면 f를 잊은 거예요. 문자열 앞 한 글자만 붙이면 됩니다."},{"symptom":"NameError","cause":"오타·대소문자","coach":"컴퓨터는 Name과 name을 다른 사람으로 봅니다. 상자 이름을 소리 내어 읽어 보게 하세요."},{"symptom":"질문만 나오고 결과 없음","cause":"input만 하고 print 없음","coach":"\"받기\"와 \"보여주기\"를 판서로 나눠 짚어 주세요."},{"symptom":"카드가 두 번 출력","cause":"실행 버튼 두 번 / print 중복","coach":"코드 맨 위부터 print 개수를 세어 보게 합니다."}],"qa":[{"q":"선생님, 한글이 깨져요/이상한 글자가 나와요","a":"입력할 때 따옴표 안에 한글을 넣었는지, 저장 인코딩이 UTF-8인지 확인. 그래도 안 되면 그 줄만 지우고 다시 치게 하세요."},{"q":"input()을 쳤는데 아무 일도 안 일어나요","a":"엔터를 안 쳤거나, 다음 줄이 실행 중입니다. \"질문이 나왔으면 커서가 거기서 기다리는 것\"이라고 설명하고 엔터를 직접 누르게 하세요."},{"q":"{name}이 그대로 나와요","a":"f 누락. \"중괄호가 글자로 보이면 f를 잊은 것\" — 한 글자만 붙이게 합니다."},{"q":"나이는 숫자인데 왜 계산이 안 되나요?","a":"input은 항상 글자를 줍니다. 지금은 \"다음 시간에 문(int)을 통과시켜 숫자로 바꾼다\"까지만 예고하고 넘어갑니다."},{"q":"변수 이름을 꼭 name으로 해야 하나요?","a":"아무 이름이나 됩니다. 단, 같은 상자를 두 철자로 쓰면 다른 상자가 됩니다. 오늘은 소문자 영어로 통일."},{"q":"카드가 두 번 나와요","a":"실행을 두 번 눌렀거나 print가 두 번 있습니다. 코드에서 print 개수를 세게 하세요."}],"tips":["input()이 문자열을 준다는 건 오늘은 소리만 하고 넘어갑니다. 2회차에 직접 터뜨려서 가르치는 게 오래 남습니다.","판서는 왼쪽에 상자 그림, 오른쪽에 코드로 나눠 쓰면 대응시키기 쉽습니다.","45분·70분·90분에 \"여기까지 된 사람 손\"으로 진도를 3번 확인하면 뒤처진 학생을 그 자리에서 잡을 수 있습니다.","첫 수업에서 저장을 못 하면 2회차에 이어 갈 수 없습니다. 마지막 5분은 반드시 저장 확인에 씁니다."]}$jt$::jsonb,
   'name = input("이름: ")
age = input("나이: ")
hobby = input("좋아하는 것: ")
mood = input("오늘 기분: ")

print("=" * 22)
