  ('py-w01-s2', 'theory', '1주 2회차 — 계산 붙이기 + 에러 3종 잡기 (2시간)', 'python', 1, 2,
   'int()로 나이를 숫자로 바꿔 계산을 붙이고, 일부러 망가뜨린 문법·실행·논리 오류 3개를 직접 고칩니다.', $jc${"goal":"내 카드에 계산(내년 나이·태어난 해)을 붙이고, 문법·실행·논리 오류를 각각 1개 이상 직접 고친다","preview":"★ 20개\n이름 : 지훈\n나이 : 14살\n내년 : 15살\n태어난 해 : 2013년\n취미 : 코딩\n기분 : good\n★ 20개","words":["int()","TypeError","ValueError","논리 오류"],"conceptTitle":"int()는 글자를 숫자로 바꾸는 문","concept":[{"code":"\"14\"","mean":"액자에 걸린 사진 — 보기만 되고 계산은 안 된다"},{"code":"14","mean":"실제 지폐 — 계산이 된다"},{"code":"int(\"14\")","mean":"문을 통과시켜 숫자로 바꾼다"},{"code":"int(input(\"나이: \"))","mean":"받자마자 숫자로 바꿔서 상자에 넣는다"},{"code":"print(\"19\" + \"1\")","mean":"\"191\" — 글자끼리는 이어 붙는다"},{"code":"print(19 + 1)","mean":"20 — 숫자끼리는 계산한다"}],"predict":{"code":"age = \"14\"\nprint(age + \"1\")\nprint(int(age) + 1)","answer":"141 / 15 — 첫 줄은 이어 붙이기, 둘째 줄은 계산"},"steps":[{"title":"오늘 할 일 3개","note":"① 지난 시간 카드 못 만든 데까지 마무리 ② 망가뜨린 코드 3개(문법·실행·논리) 고치기 ③ 업그레이드 미션 1개 이상 붙이기"},{"title":"A. 문법 오류 — 따옴표·괄호 짝","code":"name = input(\"이름: \")\nprint(f\"안녕하세요 {name}님)"},{"title":"B. 실행 오류 — int() 없이 계산","code":"age = input(\"나이: \")\nprint(f\"내년에는 {age + 1}살\")"},{"title":"C. 논리 오류 — 빨간 글씨는 없는데 결과가 이상함","code":"mood = input(\"오늘 기분: \")\nprint(\"오늘 기분은 {mood}입니다.\")"}],"debug":[{"kind":"문법","title":"문제 A — 따옴표가 닫히지 않은 코드","code":"name = input(\"이름: \")\nprint(f\"안녕하세요 {name}님)\nprint(\"카드 시작\")","symptom":"SyntaxError: unterminated string literal (detected at line 2)","check":"실행하면 \"안녕하세요 지훈님\" 다음에 \"카드 시작\"이 나온다. 따옴표는 모두 짝이 맞다.","hint":"빨간 줄이 가리키는 2번째 줄의 따옴표 개수를 세어 보세요. 따옴표는 열고 닫고 2개여야 합니다."},{"kind":"실행","title":"문제 B — 계산이 안 되는 코드","code":"age = input(\"나이: \")\nprint(f\"내년에는 {age + 1}살\")\nprint(\"카드 끝\")","symptom":"TypeError: unsupported operand type(s) for +: 'str' and 'int'","check":"나이에 14를 넣으면 \"내년에는 15살\"이 나온다.","hint":"input이 주는 것은 글자입니다. 숫자로 바꾸는 문(int)을 input 바깥에 씌워 보세요."},{"kind":"논리","title":"문제 C — 조용한 버그","code":"mood = input(\"오늘 기분: \")\nprint(\"오늘 기분은 {mood}입니다.\")\nprint(\"오늘도 수고했어요\")","symptom":"오류 없이 실행되지만 \"오늘 기분은 {mood}입니다.\"가 글자 그대로 나온다","check":"기분에 good을 넣으면 \"오늘 기분은 good입니다.\"가 나온다.","hint":"중괄호가 글자로 보이면 f를 잊은 것입니다. 단, 여기는 f-string이 아닌 줄이라 중괄호 자체가 글자입니다."}],"practice":[{"title":"확인 1 — 이 코드의 출력은?","prompt":"실행하기 전에 종이에 먼저 적고, 실행해서 맞춰 보세요.","starter":"age = \"14\"\nprint(age + \"1\")\nprint(int(age) + 1)","expect":"141\n15"},{"title":"확인 2 — 태어난 해 계산","prompt":"나이를 숫자로 받아 태어난 해(2026 - 나이 + 1)를 출력하세요.","starter":"age = int(input(\"나이: \"))\n# 여기에 print 한 줄\nprint(f\"내년 : {age + 1}살\")","expect":"나이: 14\n태어난 해 : 2013년\n내년 : 15살","hint":"f\"태어난 해 : {2026 - age + 1}년\" 처럼 식을 중괄호 안에 바로 쓸 수 있어요."}],"mistakes":[{"symptom":"TypeError: unsupported operand type(s) for +: 'str' and 'int'","cause":"int()를 빼고 계산했다"},{"symptom":"ValueError: invalid literal for int()","cause":"숫자가 아닌 글자를 넣었다 ('열네 살', 빈칸)"},{"symptom":"카드가 두 번 겹쳐 나온다","cause":"실행 버튼을 두 번 눌렀다"},{"symptom":"태어난 해가 1년 어긋난다","cause":"만 나이와 한국식 나이를 섞었다"}],"hints":["에러 이름을 먼저 읽어 보세요 — Syntax, Type, Value 중 무엇인지에 따라 고치는 곳이 다릅니다.","\"글자 + 숫자\"가 문제인지 확인해 보세요.","int(...)를 input 바깥에 씌워 보세요 → age = int(input(\"나이: \"))","빨간 글씨가 하나도 없는데 결과가 이상하면, print 안의 글자를 소리 내어 읽어 보세요."],"selfcheck":["내 파일이 실행되고 값 3개가 내 것으로 바뀌었다","문법·실행·논리 오류를 각각 1개 이상 직접 고쳤다","미션 1개 이상 붙였다","int()가 왜 필요한지 한 문장으로 설명할 수 있다","1분 발표: 내가 고친 것 / 아직 아쉬운 점"],"note":"C는 빨간 글씨가 하나도 안 뜹니다. 조용한 버그가 제일 위험해요. 그래서 실행 결과를 눈으로 꼭 확인해야 합니다.","missions":{"basic":"테두리를 = 에서 ★ 로 바꾸고, 카드에 오늘 기분 한 줄 추가하기 — print(\"★\" * 20)","challenge":"나이를 숫자로 받아 내년 나이와 태어난 해를 계산해 출력하기 — {age + 1}, {2026 - age + 1}","deep":"콜론 위치를 통일해 정렬 맞추기 + 좋아하는 것이 빈칸이면 \"아직 없음\"으로 보여 주기"},"missionsOut":{"basic":"★ 20개\n이름 : 지훈\n나이 : 14살\n기분 : good\n★ 20개","challenge":"이름 : 지훈\n나이 : 14살\n내년 : 15살\n태어난 해 : 2013년","deep":"이름        : 지훈\n나이        : 14살\n좋아하는 것 : 아직 없음\n오늘 기분   : good"}}$jc$::jsonb, $jt${"demo":"'오늘은 새로 배우는 게 없습니다. 못 만든 거 끝내기, 빨간 글씨 잡기, 그리고 카드 한 단계 업그레이드. 오늘 끝나면 카드에 계산이 들어갑니다. 그리고 오늘은 일부러 망가뜨린 코드 3개를 여러분이 직접 고칩니다.'","analogy":"\"14\"(글자)는 액자에 걸린 사진, 14(숫자)는 실제 지폐. 사진으로는 계산할 수 없고, 문(int())을 통과시켜야 계산이 됩니다. 논리 오류는 \"불은 안 났는데 엉뚱한 방으로 간 것\".","timeline":[{"min":"0~10","title":"도입 — 지난 시간 카드 확인","detail":"전원 파일을 열게 하고 3칸 체크: 코드 완성 / 실행 성공 / 저장. 여기서 못 연 학생은 옆자리와 짝. 오늘의 결과물(계산 들어간 카드)을 먼저 보여 줍니다."},{"min":"10~25","title":"개념 — int()는 문","detail":"age + 1을 다 같이 일부러 터뜨려 TypeError 빨간 글씨를 판서. 그다음 int(\"14\") 실험 → input → \"14\" → int → 14 화살표. 글자와 숫자의 차이 한 가지만."},{"min":"25~55","title":"디버깅 A·B·C (모둠 순환)","detail":"모둠별로 A(문법)·B(실행)·C(논리) 하나씩 배정, 10분 뒤 옆 모둠으로. 각 문제는 화면에 증상이 그대로 보이게 실행해 보는 것이 출발점. C는 반드시 다 같이 마무리."},{"min":"55~75","title":"내 카드에 계산 붙이기","detail":"내 카드에 내년 나이·태어난 해를 붙입니다. int()를 어디에 씌우는지 손으로 확인. 여기까지가 오늘의 필수 완성."},{"min":"75~95","title":"업그레이드 미션 선택","detail":"기본/도전/심화 중 1개 이상. 기본은 테두리·기분, 도전은 계산, 심화는 정렬·빈칸 처리. 각 미션의 예시 출력을 보여 주고 \"이게 나오면 성공\"을 기준으로 삼게 합니다."},{"min":"95~110","title":"테스트 + AI 코칭","detail":"이상한 입력(빈칸, 글자)을 직접 넣어 보게 합니다. ValueError가 나면 \"지금은 정상, 13주에 if로 막는다\"고 예고. AI에게는 에러 원인 후보만 받습니다."},{"min":"110~118","title":"저장·1분 발표","detail":"내가 고친 것 1개 / 아직 아쉬운 점 1개. 발표를 못 하겠다는 학생은 코드 한 줄을 읽고 \"이 줄은 ~한다\"만 말하게 합니다."},{"min":"118~120","title":"예고","detail":"다음 주는 계산 기호 // 와 %. \"오늘 int()를 배웠으니 다음 주엔 계산이 두 배로 늘어납니다.\""}],"board":[{"say":"각자 어디서 멈췄는지 확인, 3분은 무조건 혼자","write":"진행 상황 3칸: 코드 완성 / 실행 성공 / 저장"},{"say":"age + 1을 일부러 다 같이 터뜨린다","write":"\"14\" + 1 → TypeError (빨간 글씨 그대로 판서)"},{"say":"int(\"14\") 실험","write":"input → \"14\" → int → 14 화살표"},{"say":"에러 3종 지도","write":"문법(Syntax) / 실행(Type·Value) / 논리(조용함)"},{"say":"디버깅 A/B/C 배분","write":"A 문법 / B 실행 / C 논리 3칸 표"},{"say":"업그레이드 미션","write":"기본 / 도전 / 심화 3단 표 + 각 예시 출력"},{"say":"조용한 버그 찾는 법","write":"print()로 중간값 찍어 보기"},{"say":"저장·발표","write":"내가 고친 것 / 아직 아쉬운 점"}],"ai":[{"when":"디버깅 30~50분","what":"에러 원인 힌트만","prompt":"이 에러가 왜 나는지 힌트만 2줄로 알려줘. 고친 코드는 주지 마. 에러: TypeError: unsupported operand type(s) for +: 'str' and 'int'","rule":"정답 코드를 받았으면 지우고 다시 짜게 한다"},{"when":"업그레이드 80분","what":"기능 3안 받고 1개 고르기","prompt":"내 소개 카드에 붙일 수 있는 기능 3개만 제안해줘. 코드는 쓰지 마.","rule":"고르는 건 학생"}],"errors":[{"symptom":"TypeError ... 'str' and 'int'","cause":"int() 누락","coach":"액자 사진으로 계산하려고 했네요. 문(int)을 통과시켜 봐요."},{"symptom":"ValueError: invalid literal for int()","cause":"숫자 대신 글자·빈칸 입력","coach":"안내 문구를 '숫자로 입력해 주세요'로 바꿔 보게 하세요. 막는 건 13주 if에서."},{"symptom":"태어난 해가 1년 어긋남","cause":"만 나이/한국식 혼동","coach":"우리 반 기준을 정하고 주석으로 남기기 — 주석 습관으로 연결."},{"symptom":"고쳤는데 결과가 그대로","cause":"저장 후 실행하지 않음 / 다른 파일 실행","coach":"파일 이름을 확인하고 저장(Ctrl+S) 후 다시 실행."},{"symptom":"C를 못 찾음","cause":"오류가 안 나서 넘어감","coach":"실행 결과를 소리 내어 읽게 하세요. \"오늘 기분은 {mood}입니다\"가 이상하다는 걸 스스로 듣게."}],"qa":[{"q":"int()를 어디에 붙여요?","a":"값을 담는 순간에 붙입니다 — age = int(input(\"나이: \")). input 바깥을 감싸는 모양을 손으로 그려 보게 하세요."},{"q":"저는 계산이 되는데 친구는 TypeError가 나요","a":"한쪽은 int()가 있고 한쪽은 없습니다. 두 코드의 age 줄을 나란히 놓고 비교하게 하세요."},{"q":"빈칸으로 엔터를 쳤더니 ValueError가 나요","a":"지금 단계에서는 정상입니다. \"프로그램이 죽지 않게 막는 건 13주 if\"라고 예고만 하고 넘어갑니다."},{"q":"논리 오류 C가 뭐가 틀린지 모르겠어요","a":"실행 결과를 소리 내어 읽게 하세요. {mood}가 그대로 보이면 f를 잊은 것. 조용한 버그의 특징을 몸으로 익히는 시간입니다."},{"q":"태어난 해가 2012년으로 나와요","a":"만 나이/한국식 나이 기준 차이입니다. 반 기준을 정하고 주석으로 남기게 하세요 — 정답을 정해 주지 않습니다."}],"tips":["논리 오류 C는 반드시 다 같이 짚고 갑니다. 3주 조건문에서 가장 크게 돌아옵니다.","막힌 학생에게 코드를 주지 말고 질문 2개: \"지금 화면에 뭐가 나와야 하지?\" \"그 숫자는 어디서 왔지?\"","디버깅은 모둠 순환으로 하면 30분에 3문제를 모두 경험합니다. 한 명이 다 하면 1문제에서 30분이 갑니다.","업그레이드 미션은 예시 출력을 먼저 보여 주고 \"이게 나오면 성공\"으로 기준을 주면 채점이 필요 없어집니다."]}$jt$::jsonb,
   'name = input("이름: ")
age = int(input("나이: "))
hobby = input("좋아하는 것: ")
mood = input("오늘 기분: ")

print("★" * 20)
print(f"이름 : {name}")
print(f"나이 : {age}살")
print(f"내년 : {age + 1}살")
print(f"태어난 해 : {2026 - age + 1}년")
print(f"취미 : {hobby}")
print(f"기분 : {mood}")
print("★" * 20)', '에러가 나면 빨간 글씨를 그대로 복사해 "원인 후보 3개만, 해결은 내가 할게"라고 물어보세요.', null,
