  ('py-w01-upgrade', 'upgrade', '1주 업그레이드 미션 — 카드에 계산과 기분 한 줄', 'python', 1, 2,
   '기본/도전/심화 중 1개 이상 골라 내 카드를 한 단계 올립니다.', $jc${"goal":"내 카드에 기능 1개를 더 붙인다","missions":{"basic":"테두리 = 를 ★ 로 바꾸고, 카드에 오늘 기분 한 줄 추가하기 — print(\"★\" * 20)","challenge":"나이를 숫자로 받아 내년 나이와 태어난 해를 계산해 출력하기","deep":"콜론 위치를 통일해 정렬 맞추기 + 좋아하는 것이 빈칸이면 \"아직 없음\" 출력"},"missionsOut":{"basic":"★ 20개\n이름 : 지훈\n나이 : 14살\n기분 : good\n★ 20개","challenge":"이름 : 지훈\n나이 : 14살\n내년 : 15살\n태어난 해 : 2013년","deep":"이름        : 지훈\n나이        : 14살\n좋아하는 것 : 아직 없음\n오늘 기분   : good"},"hints":["문자열에 숫자를 곱하면 반복돼요. \"★\" * 20","태어난 해 = 올해 - 나이 + 1 (우리 반 기준)","if는 다음 주에 배웁니다. 오늘은 값으로만 처리해요."],"selfcheck":["미션 1개 이상 붙였다","내 값으로 3번 실행했다","1분 발표를 준비했다"]}$jc$::jsonb, $jt${"timeline":[{"min":"75~95","title":"미션 선택과 진행","detail":"기본(테두리·기분) → 도전(계산) → 심화(정렬·빈칸). 한 단계씩 올라가게 하고, 심화는 \"if 없이 할 수 있는 데까지\"가 규칙입니다."},{"min":"95~105","title":"확인","detail":"각 미션의 예시 출력과 내 화면을 비교하게 합니다. 다르면 어느 줄이 다른지 스스로 찾게."}],"ai":[{"when":"업그레이드 들어가기 전","what":"기능 3안 받고 1개 고르기","prompt":"내 소개 카드에 붙일 수 있는 기능 3개만 제안해줘. 코드는 쓰지 마.","rule":"고르는 건 학생"}],"errors":[{"symptom":"기본 미션도 못 끝냄","cause":"시간 부족","coach":"2줄 카드로 줄여 성공 경험 먼저. 나머지는 2주차에 이어받기."}],"tips":["잘한 학생에겐 심화보다 \"친구 코드 읽고 설명해 주기\" — 1인 운영에서 가장 효율 좋은 역할입니다.","빈칸 처리(심화)는 if가 필요하다는 걸 스스로 발견하는 게 목적입니다. 오늘은 \"아직 없음\"을 값으로 넣어 보는 데까지만."]}$jt$::jsonb,
   null, '업그레이드 아이디어가 안 떠오르면 "내 카드에 붙일 기능 3개만 제안해줘"라고 묻고 하나만 골라요.', null,
