  ('py-w02-s1', 'theory', '연산자로 용돈 계산기 만들기 (2시간)', 'python', 2, 1,
   '//·%·** 와 int()로 총액·거스름돈·지폐 개수를 계산하는 계산기를 만듭니다.', $jc${"goal":"물건 값·개수·가진 돈을 넣으면 총액, 거스름돈, 1000원짜리 장수와 남는 돈이 나온다","preview":"물건 가격: 1200\n개수: 3\n가진 돈: 5000\n총 금액: 3,600원\n거스름돈: 1,400원\n1000원짜리 1장, 남는 돈 400원\n500원짜리 0개, 남는 돈 400원","words":["산술 연산자","//","%","**"],"conceptTitle":"파이썬의 계산 기호","concept":[{"code":"3 * 4","mean":"곱하기 → 12"},{"code":"7 / 2","mean":"나누기(소수까지) → 3.5"},{"code":"7 // 2","mean":"몫만 → 3 (통째로 나누기)"},{"code":"7 % 2","mean":"나머지 → 1 (남는 조각)"},{"code":"2 ** 3","mean":"거듭제곱 → 8"},{"code":"f\"{1234567:,}\"","mean":"천 단위 콤마 → 1,234,567"},{"code":"계산 순서","mean":"* / 가 + - 보다 먼저, 괄호가 최우선"}],"predict":{"code":"print(7 / 2)\nprint(7 // 2)\nprint(7 % 2)\nprint(2 ** 3)","answer":"3.5 / 3 / 1 / 8"},"steps":[{"title":"1단계 — 값 3개 받기 (숫자로!)","code":"price = int(input(\"물건 가격: \"))\ncount = int(input(\"개수: \"))\nmoney = int(input(\"가진 돈: \"))","note":"int()를 빼면 1주차 TypeError가 그대로 재현됩니다. 오늘은 스스로 확인하게 합니다."},{"title":"2단계 — 총액과 거스름돈","code":"total = price * count\nchange = money - total"},{"title":"3단계 — 출력 (콤마로 보기 좋게)","code":"print(f\"총 금액: {total:,}원\")\nprint(f\"거스름돈: {change:,}원\")"},{"title":"4단계 — 지폐로 바꿔 보기","code":"print(f\"1000원짜리 {change // 1000}장, 남는 돈 {change % 1000}원\")","note":"// 는 통째로 몇 장인지, % 는 남는 돈. 두 기호가 한 줄에 같이 쓰입니다."},{"title":"5단계 — 내 물건 값으로 3번 실행하기","note":"편의점에서 산 물건, 문구점에서 산 물건 등 내 상황으로 바꿔 3번 실행합니다."}],"builds":[{"label":"기초","title":"① 나누기 3형제 확인","intro":"오늘의 새 기호를 눈으로 먼저 봅니다. 네 줄 실행 결과를 예상해 적고 실행.","steps":[{"title":"코드","code":"print(10 / 4)\nprint(10 // 4)\nprint(10 % 4)\nprint(4 ** 2)"}],"out":"2.5\n2\n2\n16"},{"label":"변형","title":"② 거스름돈 계산기","intro":"값을 물어보고 총액과 거스름돈만 계산합니다. 여기까지가 최소 완성.","steps":[{"title":"코드","code":"price = int(input(\"물건 가격: \"))\ncount = int(input(\"개수: \"))\nmoney = int(input(\"가진 돈: \"))\n\ntotal = price * count\nchange = money - total\n\nprint(f\"총 금액: {total:,}원\")\nprint(f\"거스름돈: {change:,}원\")"}],"out":"물건 가격: 1200\n개수: 3\n가진 돈: 5000\n총 금액: 3,600원\n거스름돈: 1,400원"},{"label":"실전","title":"③ 지폐·동전 개수까지","intro":"// 와 % 를 이어 붙여 1000원짜리, 500원짜리까지 셉니다. 오늘의 완성본.","steps":[{"title":"코드","code":"print(f\"1000원짜리 {change // 1000}장, 남는 돈 {change % 1000}원\")\nprint(f\"500원짜리 {(change % 1000) // 500}개, 남는 돈 {change % 500}원\")"},{"title":"확인","note":"1400원이면 1000원 1장 + 500원 0개 + 남는 돈 400원. 손으로 먼저 계산해 보고 비교하세요."}],"out":"1000원짜리 1장, 남는 돈 400원\n500원짜리 0개, 남는 돈 400원"}],"practice":[{"title":"실습 1 — 세 물건 합계와 평균","prompt":"가격 3개를 넣고 합계와 평균을 출력하세요. 평균은 소수 첫째 자리까지.","starter":"a = int(input(\"1번 가격: \"))\nb = int(input(\"2번 가격: \"))\nc = int(input(\"3번 가격: \"))\n# 합계와 평균을 계산해 출력","expect":"1번 가격: 1000\n2번 가격: 2500\n3번 가격: 500\n합계: 4,000원\n평균: 1333.3원","hint":"합계는 a + b + c, 평균은 합계 / 3. 소수 첫째 자리는 f\"{값:.1f}\""},{"title":"실습 2 — 5000원으로 몇 개?","prompt":"가진 돈과 물건 값만으로 몇 개 살 수 있고 얼마가 남는지 계산하세요.","starter":"money = 5000\nprice = 1200\n# 개수와 남는 돈을 구해 출력","expect":"1200원짜리 4개, 남는 돈 200원","hint":"개수는 money // price, 남는 돈은 money % price"},{"title":"실습 3 — 초를 분과 초로","prompt":"전체 초를 입력하면 몇 분 몇 초인지 출력하세요.","starter":"total = int(input(\"전체 초: \"))\n# 분과 초를 계산해 출력","expect":"전체 초: 135\n2분 15초","hint":"분은 total // 60, 초는 total % 60"},{"title":"실습 4 — 거듭제곱 예상하기","prompt":"실행 전에 값을 종이에 적고, 실행해서 맞춰 보세요.","starter":"print(2 ** 10)\nprint(10 ** 2)\nprint(5 ** 0)","expect":"1024\n100\n1"}],"mistakes":[{"symptom":"TypeError","cause":"int() 없이 곱했다"},{"symptom":"거스름돈이 -1400원","cause":"가진 돈보다 총액이 큼 (계산은 맞다, 안내 문구가 필요)"},{"symptom":"SyntaxError","cause":"print(change // 1000장) 처럼 글자를 코드 안에 썼다"},{"symptom":"거스름돈이 1400.0","cause":"/ 를 써서 소수가 됐다"}],"hints":["계산 순서를 종이에 먼저 적어 보세요.","지폐 개수는 통째로 → //, 남는 돈은 %","결과가 400.0처럼 나오면 / 를 쓴 거예요.","콤마를 넣고 싶으면 f\"…{값:,}…\" 처럼 중괄호 안에 콜론과 쉼표를 붙여요."],"selfcheck":["/ , // , % 결과가 어떻게 다른지 말할 수 있다","내 물건 값으로 3번 실행했다","거스름돈이 마이너스인 경우를 직접 만들었다","1000원짜리 장수와 남는 돈이 손계산과 같다"]}$jc$::jsonb, $jt${"demo":"'오늘 끝나면 편의점 계산기가 됩니다. 물건 값, 개수, 가진 돈만 넣으면 거스름돈까지. 새로 배우는 건 기호 2개 — // 와 % 입니다. 오늘은 계산기를 세 번 고쳐 가며 완성합니다.'","analogy":"케이크 10조각을 4명이: 10/4=2.5(반쪽까지), 10//4=2(통째로), 10%4=2(남은 조각). 1400원을 지폐로 바꾸는 것도 같습니다 — 1000원짜리는 통째로(//), 남는 돈은(%).","timeline":[{"min":"0~10","title":"도입 — 지난 주 카드 확인","detail":"카드 파일을 열어 계산이 들어간 학생/안 들어간 학생을 구분. 오늘 결과물(계산기)을 먼저 보여 주고, 지난 주 int()를 한 줄로 복습."},{"min":"10~30","title":"개념 — 나누기 3형제","detail":"판서로 10/4, 10//4, 10%4, 4**2. 예상 적기(2분) → 실행 → 확인. 예측이 틀린 학생에게 이유를 말하게 하면 개념이 굳습니다."},{"min":"30~55","title":"따라 만들기 ② 거스름돈 계산기","detail":"세 값 받기 → total → change → 출력. 콤마(:,)는 여기서 처음 — 한 줄만 넣고 나머지는 학생이."},{"min":"55~75","title":"따라 만들기 ③ 지폐 개수","detail":"// 와 % 를 한 줄에 같이 쓰는 부분이 오늘의 절정. change // 1000 과 change % 1000 을 판서로 나란히."},{"min":"75~95","title":"미니 실습 1~3","detail":"1번(합계·평균)은 전원, 2번(몇 개 살 수 있나)은 대부분, 3번(초→분)은 심화. 빨리 끝난 학생은 4번과 옆 친구 확인."},{"min":"95~110","title":"오류·경계 실험","detail":"가진 돈이 부족한 경우(마이너스 거스름돈)를 직접 만들게 합니다. 계산은 맞고 안내가 없다는 걸 발견 → 3주 if 예고. 0으로 나누기(ZeroDivisionError)도 30초 시연."},{"min":"110~118","title":"AI + 저장·발표","detail":"AI에게 \"내 예상이 맞는지 틀린 것만\" 검산을 받습니다. 저장 후 1분 발표: 내가 바꾼 물건 상황과 결과."},{"min":"118~120","title":"예고","detail":"다음 시간엔 계산기를 영수증 표로 바꿉니다. \"숫자는 맞는데 안 예뻐서 손님이 안 봐요\"로 동기 부여."}],"board":[{"say":"지난주에 나이 계산했죠? 그게 계산이었습니다","write":"+ - *"},{"say":"나누기는 세 가지가 있습니다","write":"10 / 4 = 2.5 / 10 // 4 = 2 / 10 % 4 = 2"},{"say":"왜 두 개가 필요할까?","write":"1400원 → 1000원 1장, 남는 400원"},{"say":"계산 순서","write":"price * count 먼저, 그다음 빼기"},{"say":"결과를 변수에 담으면 다시 쓸 수 있다","write":"total = price * count / change = money - total"},{"say":"콤마는 출력에서만","write":"f\"{total:,}원\""},{"say":"함정 1","write":"int 빼고 곱하면 TypeError — 1주 복습"},{"say":"함정 2","write":"0으로 나누면 ZeroDivisionError"}],"ai":[{"when":"예측 단계 15분","what":"검산만 받기","prompt":"내 예상: 10/4=2.5, 10//4=2, 10%4=2, 4**2=16. 틀린 것만 알려줘. 설명은 한 줄씩.","rule":"AI 없이 먼저 적게 하고, 적은 뒤에만 연다"},{"when":"실습 3 막힐 때 90분","what":"원인 힌트만","prompt":"초를 분과 초로 나누려는데 135초가 2분 15초가 안 나와. 내 코드는 total // 60 과 total % 60 이야. 뭐가 문제인지 힌트만 1줄.","rule":"코드를 새로 써 달라고 하지 않기"}],"errors":[{"symptom":"TypeError 곱하기","cause":"int() 누락","coach":"1주 2회차와 같은 실수예요 — 숫자로 바꿨는지 확인."},{"symptom":"결과가 1400.0","cause":"/ 를 씀","coach":"지폐 개수는 통째로 — //. 소수가 나오면 기호부터 봅니다."},{"symptom":"모두 0이 나옴","cause":"int() 두 번 겹침 또는 변수 이름 오타","coach":"변수 표를 종이에 그려 보게."},{"symptom":"ZeroDivisionError","cause":"개수에 0 입력","coach":"오늘은 \"0으로는 나눌 수 없다\"만 확인. 막는 건 if."},{"symptom":"콤마가 안 붙음","cause":"중괄호 안 콜론 위치","coach":"{값:,} 모양을 판서로 한 번 더."}],"qa":[{"q":"// 랑 % 가 헷갈려요","a":"케이크 조각 비유로 돌아갑니다. \"통째로 몇 개(//), 남은 조각(%)\"을 손으로 세게 하세요."},{"q":"콤마는 어디에 붙여요?","a":"출력할 때만 붙입니다. f\"{total:,}원\" — 중괄호 안 값 뒤에 콜론과 쉼표. 계산 결과 자체는 바뀌지 않습니다."},{"q":"평균이 1333.33333 나와요","a":"f\"{avg:.1f}\"로 소수 첫째 자리까지 자릅니다. 반올림된다는 것도 함께 확인."},{"q":"거스름돈이 마이너스로 나와요","a":"계산은 맞습니다. 가진 돈이 부족한 상황을 프로그램이 막지 못한다는 것 — if 예고로 연결."},{"q":"500원짜리 개수가 이상해요","a":"(change % 1000) // 500 처럼 남는 돈에서 다시 세야 합니다. 괄호를 먼저 계산한다는 규칙을 확인."}],"tips":["판서는 계산 과정을 세로로(총액 → 거스름돈 → 지폐 개수) 쓰면 코드 순서를 그대로 따라옵니다.","예측 적기 2분을 반드시 넣으세요. 오늘 개념은 예측이 틀려야 기억에 남습니다.","0으로 나누기 시연은 30초만. 학생이 직접 0을 넣어 보게 하면 웃으면서 기억합니다."]}$jt$::jsonb,
   'price = int(input("물건 가격: "))
count = int(input("개수: "))
money = int(input("가진 돈: "))

total = price * count
change = money - total

print(f"총 금액: {total:,}원")
print(f"거스름돈: {change:,}원")
print(f"1000원짜리 {change // 1000}장, 남는 돈 {change % 1000}원")
print(f"500원짜리 {(change % 1000) // 500}개, 남는 돈 {change % 500}원")', '내가 먼저 예상값을 적은 뒤에만 AI에게 "틀린 것만 알려줘"라고 물어보세요.', null,
