   'python', true, 30),
  ('py-w03-s1', 'theory', 'if로 나이별 요금 안내 만들기 (2시간)', 'python', 3, 1,
   'if/elif/else로 갈림길을 만들고, 경계값을 직접 실행해 확인합니다.', $jc${"goal":"나이를 넣으면 유아·어린이·청소년·성인 요금 중 하나가 나오고, 경계값에서 결과가 바뀌는 것을 확인한다","preview":"나이: 13\n어린이 요금: 3,000원","words":["조건","if","elif / else","들여쓰기"],"conceptTitle":"조건문은 갈림길 표지판","concept":[{"code":"if 조건:","mean":"조건이 True일 때 아래(들여쓰기)를 실행"},{"code":"elif 다른 조건:","mean":"위가 아니고 이게 True일 때"},{"code":"else:","mean":"위가 전부 아닐 때"},{"code":":","mean":"조건 줄 끝에 반드시 콜론"},{"code":"들여쓰기 4칸","mean":"이게 없으면 조건문이 아니다"},{"code":"= vs ==","mean":"= 는 넣기, == 는 같은지 물어보기"},{"code":"age < 14","mean":"14보다 작을 때(14는 포함하지 않음)"}],"predict":{"code":"age = 14\n\nif age >= 20:\n    print(\"성인\")\nelif age >= 13:\n    print(\"청소년\")\nelse:\n    print(\"어린이\")","answer":"청소년 — 첫 줄이 False라서 둘째 줄에서 걸립니다"},"steps":[{"title":"1단계 — 나이 받기","code":"age = int(input(\"나이: \"))"},{"title":"2단계 — 갈래 2개 (기초)","code":"if age < 20:\n    print(\"청소년 이하\")\nelse:\n    print(\"성인\")"},{"title":"3단계 — 갈래 3개","code":"if age < 8:\n    print(\"유아 요금: 무료\")\nelif age < 14:\n    print(\"어린이 요금: 3,000원\")\nelse:\n    print(\"청소년 또는 성인\")"},{"title":"4단계 — 갈래 4개 (오늘의 완성)","code":"elif age < 20:\n    print(\"청소년 요금: 5,000원\")\nelse:\n    print(\"성인 요금: 8,000원\")"},{"title":"5단계 — 경계값 5번 실행","note":"6, 10, 13, 15, 20을 넣어 결과가 바뀌는 곳을 찾으세요. 바로 그 숫자가 경계값입니다."}],"builds":[{"label":"기초","title":"① 하나의 if — 성인인가?","intro":"조건문의 생김새부터. if·콜론·들여쓰기 세 가지를 몸에 익힙니다.","steps":[{"title":"코드","code":"age = int(input(\"나이: \"))\n\nif age >= 20:\n    print(\"성인입니다\")\nelse:\n    print(\"성인이 아닙니다\")"}],"out":"나이: 21\n성인입니다"},{"label":"변형","title":"② 세 갈래로 늘리기","intro":"elif를 붙이면 갈래가 늘어납니다. 순서가 중요하다는 것도 여기서 처음 봅니다.","steps":[{"title":"코드","code":"age = int(input(\"나이: \"))\n\nif age < 8:\n    print(\"유아: 무료\")\nelif age < 20:\n    print(\"학생: 5,000원\")\nelse:\n    print(\"성인: 8,000원\")"}],"out":"나이: 15\n학생: 5,000원"},{"label":"실전","title":"③ 요금표 네 갈래 (오늘의 완성)","intro":"경계를 8 / 14 / 20으로 잡습니다. 경계값을 직접 넣어 확인하는 것이 진짜 실력.","steps":[{"title":"코드","code":"age = int(input(\"나이: \"))\n\nif age < 8:\n    print(\"유아 요금: 무료\")\nelif age < 14:\n    print(\"어린이 요금: 3,000원\")\nelif age < 20:\n    print(\"청소년 요금: 5,000원\")\nelse:\n    print(\"성인 요금: 8,000원\")"},{"title":"확인","note":"7 → 무료 / 8 → 어린이 / 13 → 어린이 / 14 → 청소년 / 20 → 성인. 다섯 번 실행해 표를 채우세요."}],"out":"나이: 8\n어린이 요금: 3,000원"}],"practice":[{"title":"실습 1 — 짝수와 홀수","prompt":"숫자를 넣으면 짝수인지 홀수인지 출력하세요.","starter":"n = int(input(\"숫자: \"))\n# 나머지 % 2 를 이용해 if를 완성","expect":"숫자: 7\n7은 홀수입니다","hint":"n % 2 == 0 이면 짝수. 아니면 홀수."},{"title":"실습 2 — 60점 합격","prompt":"점수를 넣으면 합격/불합격을 출력하세요. 60점도 합격입니다.","starter":"score = int(input(\"점수: \"))\n# if 한 줄을 채우세요","expect":"점수: 60\n합격입니다","hint":"score >= 60 이면 합격. = 를 하나만 쓰면 SyntaxError."},{"title":"실습 3 — 경계값 맞히기","prompt":"아래 코드에 13, 14를 넣으면 각각 무엇이 나올지 먼저 적고 실행하세요.","starter":"age = 13\nif age < 14:\n    print(\"어린이\")\nelse:\n    print(\"청소년\")","expect":"13 → 어린이 / 14 → 청소년"},{"title":"실습 4 — = 와 == 구분","prompt":"두 코드 중 실행되는 것과 오류가 나는 것을 구분하고, 이유를 적으세요.","starter":"a = 13\nprint(a == 13)\n# print(a = 13)  ← 이 줄의 주석을 풀면?","expect":"True\nSyntaxError — = 는 넣기, == 는 비교"}],"mistakes":[{"symptom":"IndentationError","cause":"들여쓰기 4칸이 아니거나 탭·스페이스가 섞임"},{"symptom":"SyntaxError: expected ':'","cause":"콜론 누락"},{"symptom":"if age = 13 에서 SyntaxError","cause":"비교는 =="},{"symptom":"조건이 맞는데 아무것도 안 나온다","cause":"print가 if 블록 밖으로 나갔거나 들여쓰기가 어긋남"}],"hints":["조건 줄 끝에 콜론이 있는지 봐요.","들여쓰기를 지우면 무슨 일이 나는지 직접 확인해 보세요.","물어볼 땐 ==, 넣을 땐 =","경계값(8, 14, 20)을 직접 넣어 보면 어디가 틀렸는지 보여요."],"selfcheck":["경계값 8·14·20에서 결과가 바뀌는 걸 확인했다","= 와 == 의 차이를 예로 말할 수 있다","들여쓰기를 지웠을 때 나는 에러를 봤다","내 요금표로 바꿔 3번 실행했다"]}$jc$::jsonb, $jt${"demo":"'지금까지는 위에서 아래로 한 줄씩만 갔습니다. 오늘부터 컴퓨터가 생각합니다. 나이를 넣으면 네 갈래 중 하나로 갈라져요. 오늘의 핵심은 순서와 경계값입니다.'","analogy":"조건문은 갈림길 표지판 — 처음 표지판이 맞으면 그 길로 가고 다른 길은 쳐다보지 않는다. 그래서 순서가 중요합니다. 경계값은 \"문턱\" — 8살은 어린이 쪽, 7살은 유아 쪽.","timeline":[{"min":"0~10","title":"도입 — 갈림길이 필요한 순간","detail":"지난 주 계산기에서 거스름돈이 마이너스로 나온 화면을 띄우고 \"프로그램이 상황을 판단하게 하려면?\"으로 시작."},{"min":"10~30","title":"개념 — if·콜론·들여쓰기","detail":"판서로 분기 그림 3갈래. if/elif/else를 한 줄씩. 들여쓰기를 일부러 지워 IndentationError를 다 같이 봅니다."},{"min":"30~50","title":"따라 만들기 ① 성인인가","detail":"가장 작은 if. 전원 실행 확인. 콜론·들여쓰기 오류를 그 자리에서 잡습니다."},{"min":"50~70","title":"따라 만들기 ② 세 갈래","detail":"elif 추가. \"위가 아니고\"를 소리 내어 읽게 합니다."},{"min":"70~95","title":"③ 네 갈래 + 경계값 표","detail":"7·8·13·14·20을 넣어 결과 표를 채웁니다. 표가 채워지면 조건문을 이해한 것입니다."},{"min":"95~110","title":"미니 실습 1~4","detail":"1번(짝수/홀수) 전원, 2번(60점) 전원, 3번(경계값 예상) 설명까지, 4번(= vs ==)은 오류를 직접 만나게."},{"min":"110~117","title":"AI + 정리","detail":"AI에게 \"우리 반 요금 기준에서 결과가 이상해지는 나이 5개만\" 받아 직접 실행해 확인."},{"min":"117~120","title":"저장·예고","detail":"저장 후 다음 시간 예고: \"오늘 코드의 순서를 일부러 뒤집으면 어떻게 될까요? 다음 시간에 조용한 버그로 만납니다.\""}],"board":[{"say":"오늘부턴 갈라집니다","write":"분기 그림 3갈래"},{"say":"if = 만약 ~라면","write":"if age < 8:"},{"say":"콜론과 들여쓰기","write":"4칸 상자 그려서 \"이 안에 있어야 실행\""},{"say":"elif = 위가 아니고","write":"위에서부터 화살표"},{"say":"else = 나머지 전부","write":"마지막 갈래"},{"say":"== 질문, = 넣기","write":"age = 13 vs age == 13"},{"say":"경계값 표","write":"7 · 8 · 13 · 14 · 20"},{"say":"함정","write":"들여쓰기 지워 IndentationError 즉석 시연"}],"ai":[{"when":"35~45분","what":"갈래 기준 질문 2개","prompt":"중학생 요금 기준을 4단계로 나눈다면 경계를 어디로 두면 좋을까? 근거만 2줄.","rule":"기준은 학생이 정하고 근거만 참고"},{"when":"110분","what":"경계값 점검","prompt":"내 요금 기준: 8 미만 무료, 14 미만 3000원, 20 미만 5000원, 나머지 8000원. 결과가 이상해지는 나이 5개만 알려줘.","rule":"받은 나이를 직접 실행해 확인한 것만 인정"}],"errors":[{"symptom":"IndentationError","cause":"공백/탭 혼용","coach":"4칸 스페이스로 통일. 탭은 쓰지 않기."},{"symptom":"expected ':'","cause":"콜론","coach":"조건 줄 끝엔 항상 콜론."},{"symptom":"모두 else만 실행","cause":"int() 누락 → 문자열 비교","coach":"숫자 비교인지 글자 비교인지 확인."},{"symptom":"경계에서 한 칸씩 어긋남","cause":"< 와 <= 선택","coach":"\"14살은 어린이? 청소년?\"을 말로 정하고 기호를 고르게."},{"symptom":"print가 두 번 나옴","cause":"들여쓰기 위치","coach":"if 블록 안/밖을 상자 그림으로 표시."}],"qa":[{"q":"elif를 if로 또 쓰면 안 되나요?","a":"쓸 수는 있지만 그러면 앞 조건과 상관없이 각각 판단합니다. \"위가 아니고\"의 뜻이 필요할 때 elif."},{"q":"14살이 왜 청소년이에요? 어린이 아닌가요?","a":"age < 14 이므로 14는 어린이가 아닙니다. 경계값을 말로 정하고 기호를 고르게 하세요 — 이게 경계값 사고입니다."},{"q":"들여쓰기를 스페이스로 몇 칸?","a":"4칸으로 통일합니다. 탭과 스페이스를 섞으면 IndentationError가 납니다."},{"q":"조건이 맞는데 결과가 안 나와요","a":"print가 if 블록 안에 있는지 확인. 상자 그림(들여쓰기)을 그려 보게 하세요."},{"q":"and는 언제 배워요?","a":"다음 시간(2회차)에 바로 배웁니다. 오늘은 한 조건씩만."}],"tips":["예측 정답은 청소년. if age >= 13 을 위로 올리면 20도 청소년이 됩니다 — 2회차 논리 오류 재료.","경계값 표를 칠판에 그려 두고 학생이 실행 결과를 채우게 하면 5분 만에 이해도가 드러납니다.","들여쓰기 오류는 반드시 한 번 다 같이 겪게 하세요. 글로 설명하는 것보다 10배 빠릅니다."]}$jt$::jsonb,
   'age = int(input("나이: "))

if age < 8:
    print("유아 요금: 무료")
elif age < 14:
    print("어린이 요금: 3,000원")
elif age < 20:
    print("청소년 요금: 5,000원")
else:
    print("성인 요금: 8,000원")', '갈래 기준을 정할 때 "근거만 2줄"로 물어보세요. 기준을 정하는 건 내가!', null,
   'python', true, 10),
  ('py-w03-s2', 'theory', '3주 2회차 — 조건 순서 잡고 등급 계산기 (2시간)', 'python', 3, 2,
   '순서 논리 오류를 잡고 and/or로 등급 계산기를 완성합니다. 오류가 안 나는 버그를 찾는 수업.', $jc${"goal":"에러가 안 나는데 답이 틀리는 코드를 고치고, and/or로 등급 계산기를 완성한다","preview":"점수: 85\n출석률(%): 90\n85점 → B등급\n수료증 발급 대상입니다.","words":["논리 오류","and / or","범위 검사"],"conceptTitle":"표지판은 위에서부터, 한 번만","concept":[{"code":"if score >= 60: ...\nelif score >= 80: ...","mean":"85점은 첫 줄에서 이미 True → 뒤는 보지 않는다"},{"code":"A and B","mean":"둘 다 맞아야 True"},{"code":"A or B","mean":"하나만 맞아도 True"},{"code":"not A","mean":"뒤집기"},{"code":"score < 0 or score > 100","mean":"범위 밖 입력 막기"},{"code":"grade in (\"A\", \"B\")","mean":"여러 값 중 하나인지 확인"}],"predict":{"code":"score = 85\nif score >= 60:\n    print(\"B\")\nelif score >= 80:\n    print(\"A\")","answer":"B — 첫 줄이 True라서 elif는 아예 보지 않습니다"},"steps":[{"title":"오늘 할 일","note":"① 요금 안내 마무리 ② 조용한 논리 오류 잡기 ③ 등급 계산기 완성 ④ 미션"},{"title":"순서가 결과를 바꾼다 — 왜 다 B가 나올까?","code":"if score >= 60:\n    grade = \"B\"\nelif score >= 80:\n    grade = \"A\""},{"title":"고치는 두 방법","note":"① 큰 수(좁은 문)를 먼저 ② >= 대신 < 로 뒤집어 쓰기"},{"title":"등급 계산기 뼈대 — 빈칸 채우기","code":"score = int(input(\"점수: \"))\nattend = int(input(\"출석률(%): \"))\n\nif score >= 90:\n    grade = \"A\"\nelif score >= 80:\n    grade = \"B\"\nelif score >= 70:\n    grade = \"C\"\nelse:\n    grade = \"D\"\n\nprint(f\"{score}점 → {grade}등급\")\n\nif ______ and ______:\n    print(\"수료증 발급 대상입니다.\")\nelse:\n    print(\"다음 주에 한 번 더 도전해 보세요.\")"}],"debug":[{"kind":"문법","title":"문제 A — elif 뒤에 나온 else","code":"score = int(input(\"점수: \"))\n\nif score >= 90:\n    grade = \"A\"\nelse:\n    grade = \"D\"\nelif score >= 80:\n    grade = \"B\"\n\nprint(grade)","symptom":"SyntaxError: invalid syntax (elif 줄)","check":"90·85·75·65를 넣으면 A·B·C·D가 차례대로 나온다.","hint":"else는 조건문의 마지막입니다. else 아래에 elif를 둘 수 없습니다. 순서를 큰 수부터 다시 세워 보세요."},{"kind":"실행","title":"문제 B — 점수가 글자로 들어온 코드","code":"score = input(\"점수: \")\nattend = int(input(\"출석률(%): \"))\n\nif score >= 90:\n    grade = \"A\"\nelse:\n    grade = \"D\"","symptom":"TypeError: '>=' not supported between instances of 'str' and 'int'","check":"점수 95를 넣으면 A가 나온다.","hint":"input은 글자를 줍니다. 비교하려면 int()가 필요합니다."},{"kind":"논리","title":"문제 C — 조용한 순서 버그","code":"score = 85\n\nif score >= 70:\n    grade = \"C\"\nelif score >= 80:\n    grade = \"B\"\nelif score >= 90:\n    grade = \"A\"\nelse:\n    grade = \"D\"\n\nprint(f\"{score}점 → {grade}등급\")","symptom":"오류 없이 \"85점 → C등급\" — 85는 B여야 한다","check":"85 → B, 95 → A, 75 → C, 65 → D","hint":"조건을 위에서부터 읽어 보세요. 85는 첫 줄 70 이상에서 이미 걸립니다. 좁은 문을 위로 올리세요."}],"practice":[{"title":"확인 1 — and 인가 or 인가","prompt":"수료증 조건 \"A 또는 B이면서 출석 80 이상\"을 코드로 옮기세요.","starter":"grade = \"B\"\nattend = 75\nif ______:\n    print(\"수료증 대상\")\nelse:\n    print(\"다음 기회에\")","expect":"다음 기회에","hint":"grade in (\"A\", \"B\") and attend >= 80 — 둘 다 맞아야 하므로 and."},{"title":"확인 2 — 범위 검사","prompt":"0~100 밖의 점수를 막는 조건을 맨 위에 넣으세요.","starter":"score = 105\n# 맨 위에 범위 검사 if를 넣고, 아래는 else 안으로 들여쓰기","expect":"0~100 사이로 다시 입력해 주세요.","hint":"if score < 0 or score > 100: — 둘 중 하나만 맞아도 막아야 하므로 or."}],"mistakes":[{"symptom":"조건을 뒤집었더니 등급이 다 틀림","cause":"넓은 조건을 위에 두면 뒤가 굶는다"},{"symptom":"수료증이 항상 나온다","cause":"and 대신 or / 괄호 오류"},{"symptom":"105점도 A","cause":"범위 검사가 없다"},{"symptom":"else 아래 elif를 써서 SyntaxError","cause":"else는 마지막"}],"hints":["85를 넣으면 첫 줄이 True인지 확인해 보세요.","표지판은 위에서부터, 한 번만 지나갑니다.","범위 검사는 맨 위에 score < 0 or score > 100","and는 둘 다, or는 하나만 — 말로 읽어 보면 대부분 잡혀요."],"selfcheck":["85·90·0·105를 넣어 모두 확인했다","순서를 바꿨을 때 왜 틀리는지 말로 설명할 수 있다","and 가 무슨 뜻인지 예로 들 수 있다","미션 1개 이상 붙였다"],"missions":{"basic":"점수는 맞는데 출석률이 80 미만이면 \"출석이 조금 아쉬워요\" 문구로 나눠 출력하기","challenge":"범위 검사(0~100)를 넣어 105점·-5점에 안내 문구가 나오게 하기","deep":"등급마다 다른 격려 문구를 붙이고, 수료증까지 몇 점 남았는지 계산해 출력하기 — {90 - score}"},"missionsOut":{"basic":"85점 → B등급\n수료증은 출석 80%부터예요. 지금 70%","challenge":"점수: 105\n0~100 사이로 다시 입력해 주세요.","deep":"85점 → B등급\n다음 주에 한 번 더 도전해 보세요. (수료증까지 5점)"}}$jc$::jsonb, $jt${"demo":"'오늘 제일 중요한 순간입니다. 빨간 글씨가 안 뜨는데 답이 틀린 코드를 보여 줄 거예요. 이걸 잡으면 진짜로 아는 겁니다. 오늘 두 시간은 조용한 버그 사냥입니다.'","analogy":"조건문은 한 번 지나가면 다시 안 돌아옵니다. 넓은 문을 위에 두면 뒤가 굶어 죽어요 — 좁은 문을 위에, 넓은 문을 아래에. and는 \"두 자물쇠\", or는 \"둘 중 하나만 열려도 되는 문\".","timeline":[{"min":"0~10","title":"도입 — 지난 시간 코드 점검","detail":"3주 1회차 요금 안내를 연다. 경계값 5개를 다시 넣어 보고, 순서를 뒤집으면 어떻게 되는지 예고."},{"min":"10~25","title":"개념 — 순서와 and/or","detail":"85점 코드를 판서로 한 줄씩. \"첫 줄에서 걸리면 뒤는 안 본다\"를 화살표로. and/or 진리표 4칸."},{"min":"25~60","title":"디버깅 A·B·C","detail":"A(문법: else 뒤 elif)·B(실행: int 누락)·C(논리: 순서). C는 결과를 나란히 띄워 \"85 → C\"를 보고 스스로 이상함을 느끼게. 모둠 순환 15분씩."},{"min":"60~85","title":"등급 계산기 완성","detail":"빈칸 채우기 → 내 점수로 실행 → 4개 점수 검증(95·85·75·65). 여기까지가 필수."},{"min":"85~105","title":"미션 3단계","detail":"기본(출석 문구)·도전(범위 검사)·심화(격려·남은 점수). 각 예시 출력과 비교하게 합니다."},{"min":"105~114","title":"AI로 반례 찾기","detail":"\"결과가 이상해지는 입력 5개만\" 받아 직접 실행. AI 답을 그대로 믿지 않고 실행으로 확인하는 습관."},{"min":"114~118","title":"저장·발표","detail":"내가 고친 조용한 버그 1개를 30초로 설명. 못 하면 코드의 그 줄을 읽게."},{"min":"118~120","title":"예고","detail":"다음 주는 4주 미니 프로젝트. \"오늘 배운 조건문으로 추천기를 만듭니다.\""}],"board":[{"say":"3주 1회차 코드 열기, 내 나이 기준으로 바꿨는지","write":"완성/미완성 체크"},{"say":"순서 뒤집힌 코드를 같이 실행","write":"85점 → B / A가 안 나오는 이유 화살표"},{"say":"고치는 두 방법","write":"① 큰 수 먼저 ② < 로 뒤집기"},{"say":"and / or 표","write":"진리표 4칸 (두 자물쇠 / 한 문)"},{"say":"등급 표","write":"90 / 80 / 70 / 나머지"},{"say":"범위 검사","write":"score < 0 or score > 100 맨 위"},{"say":"조용한 버그 찾는 3단계","write":"① 결과 읽기 ② 기대값 적기 ③ 조건 순서 보기"},{"say":"업그레이드","write":"기본 / 도전 / 심화 + 예시 출력"}],"ai":[{"when":"70~85분","what":"조건문 구멍(반례) 찾기","prompt":"내 등급 기준: 90 이상 A, 80 이상 B, 70 이상 C, 나머지 D, 점수는 0~100. 이 기준에서 결과가 이상해지는 입력 5개만 알려줘. 코드는 쓰지 마.","rule":"받은 입력을 직접 실행해 확인한 것만 인정"},{"when":"105분","what":"내 디버깅 설명 검사","prompt":"내 설명: '85가 첫 번째 if에서 걸려서 C가 나왔어요. 그래서 큰 수를 위로 올렸어요.' 틀린 부분만 짚어줘.","rule":"설명 검사만, 코드 재작성 금지"}],"errors":[{"symptom":"전부 같은 등급","cause":"조건 순서","coach":"위에서 한 번 맞으면 끝 — 좁은 문을 위로."},{"symptom":"수료증이 항상 나옴","cause":"and/or 혼동","coach":"둘 다 맞아야 한다면 and. 소리 내어 읽어 보게."},{"symptom":"105점도 A","cause":"범위 검사 없음","coach":"도전 미션으로 승격."},{"symptom":"elif에서 SyntaxError","cause":"else 뒤에 elif","coach":"else는 마지막. 순서를 큰 수부터 다시."},{"symptom":"들여쓰기 때문에 else가 따로 동작","cause":"if와 else의 짝","coach":"세로줄을 맞춰 어느 if의 else인지 표시."}],"qa":[{"q":"왜 85가 B가 아니라 C예요?","a":"첫 조건이 70 이상이라 85가 거기서 걸립니다. 표지판 비유로 돌아가 \"먼저 만나는 표지판이 이긴다\"를 확인."},{"q":"and와 or를 자꾸 바꿔 써요","a":"\"둘 다 필요하면 and, 하나만 필요하면 or\"를 문장으로 읽게 하세요. 수료증은 둘 다 필요 → and."},{"q":"범위 검사를 왜 맨 위에 두나요?","a":"아래에 두면 105가 A로 먼저 처리됩니다. 막는 문은 입구에 세운다."},{"q":"if를 두 개 쓰면 안 되나요?","a":"됩니다. 다만 서로 영향을 주지 않아서 순서 실수를 찾기 어려워집니다. 오늘은 elif로 \"한 갈래만\"을 연습."},{"q":"수료증까지 몇 점 남았는지 어떻게 계산해요?","a":"90 - score. 85면 5점. 심화 미션에서 f-string 안에 식을 바로 넣어 봅니다."}],"tips":["C(논리 오류)는 모둠별로 서로 다른 순서 오류를 주고 바꿔 고치게 하면 15분이면 정리됩니다.","조용한 버그는 \"기대값을 먼저 적기\"로 잡습니다. 실행 전에 정답을 종이에 쓰게 하세요.","AI 반례를 받으면 반드시 직접 실행해 확인 — 이 습관을 오늘 한 번 각인시킵니다."]}$jt$::jsonb,
   'score = int(input("점수: "))
attend = int(input("출석률(%): "))

if score < 0 or score > 100:
    print("0~100 사이로 다시 입력해 주세요.")
else:
    if score >= 90:
        grade = "A"
    elif score >= 80:
        grade = "B"
    elif score >= 70:
        grade = "C"
    else:
        grade = "D"

    print(f"{score}점 → {grade}등급")

    if grade in ("A", "B") and attend >= 80:
        print("수료증 발급 대상입니다.")
    else:
        print(f"다음 주에 한 번 더 도전해 보세요. (수료증까지 {90 - score}점)")', '"내 기준에서 결과가 이상해지는 입력 5개만 알려줘. 코드는 쓰지 마." — 받은 입력은 꼭 직접 실행해 확인!', null,
   'python', true, 20),
  ('py-w04-s1', 'theory', '4주 1회차 — 미니 프로젝트 설계와 골격 (2시간)', 'python', 4, 1,
   '배운 것을 한 프로그램으로 묶습니다. 오늘의 새 문법은 없고, 설계와 골격에 집중합니다.', $jc${"goal":"질문 2개로 4가지 추천이 나오는 프로그램 골격을 만들고, 설계 5칸을 종이에 채운다","preview":"=== 오늘 뭐 먹지? ===\n밥/면 중에 뭐가 당겨요? (밥/면): 밥\n매운 거 좋아해요? (yes/no): yes\n추천: 제육덮밥 🔥","words":["설계","경우의 수","and"],"conceptTitle":"경우의 수를 세는 게 설계","concept":[{"code":"질문 1개 = 갈래 2개","mean":"밥 / 면"},{"code":"질문 2개 = 갈래 4개","mean":"2 × 2 = 4"},{"code":"질문 3개 = 8갈래","mean":"3개는 너무 많다는 걸 직접 세어 보기"},{"code":"kind == \"밥\" and spicy == \"yes\"","mean":"두 조건을 동시에 (3주 복습)"},{"code":"else","mean":"마지막 남은 갈래"}],"predict":{"code":"q1 = \"밥\"\nq2 = \"no\"\n\nif q1 == \"밥\" and q2 == \"yes\":\n    print(\"A\")\nelif q1 == \"밥\" and q2 == \"no\":\n    print(\"B\")\nelse:\n    print(\"C\")","answer":"B — 두 조건이 모두 맞는 줄에서 걸립니다"},"steps":[{"title":"설계 5칸 — 코드 치기 전에 종이에 먼저","note":"① 무엇을 물어볼까 ② 무엇을 저장할까 ③ 어떻게 갈라질까 ④ 무엇을 보여줄까 ⑤ 무엇을 빼야 안전할까(개인정보)"},{"title":"골격 코드 — 따라 치고 내 주제로 바꾸기","code":"kind = input(\"밥/면 중에 뭐가 당겨요? (밥/면): \")\nspicy = input(\"매운 거 좋아해요? (yes/no): \")"},{"title":"4갈래 조합 표를 종이에","note":"밥·매움 / 밥·안매움 / 면·매움 / 면·안매움 — 네 줄을 채운 뒤 코드의 if 4개와 1:1로 맞춥니다."},{"title":"내 주제로 바꾸는 3가지 방향 (하나 고르기)","note":"① 메뉴 추천기 ② 오늘 뭐 입지? ③ 나만의 퀴즈(성향 테스트)"}],"builds":[{"label":"기초","title":"① 질문 1개 — 2갈래 추천","intro":"가장 작은 추천기. 경우의 수 2개.","steps":[{"title":"코드","code":"weather = input(\"오늘 날씨는? (맑음/비): \")\n\nif weather == \"맑음\":\n    print(\"추천: 운동화\")\nelse:\n    print(\"추천: 우산\")"}],"out":"오늘 날씨는? (맑음/비): 비\n추천: 우산"},{"label":"변형","title":"② 질문 2개 — 4갈래 추천","intro":"3주 조건문 + and. 네 조합을 if 4개로 나눕니다.","steps":[{"title":"코드","code":"kind = input(\"밥/면? (밥/면): \")\nspicy = input(\"매운 거 좋아해요? (yes/no): \")\n\nif kind == \"밥\" and spicy == \"yes\":\n    print(\"추천: 제육덮밥\")\nelif kind == \"밥\" and spicy == \"no\":\n    print(\"추천: 카레라이스\")\nelif kind == \"면\" and spicy == \"yes\":\n    print(\"추천: 짬뽕\")\nelse:\n    print(\"추천: 잔치국수\")"}],"out":"밥/면? (밥/면): 면\n매운 거 좋아해요? (yes/no): yes\n추천: 짬뽕"},{"label":"실전","title":"③ 내 주제로 바꾼 추천기","intro":"오늘의 완성본. 질문 2개와 추천 4개를 내 주제로 바꿉니다. 이모지·말투도 내 취향으로.","steps":[{"title":"예시 — 오늘 뭐 입지?","code":"print(\"=== 오늘 뭐 입지? ===\")\n\ntemp = input(\"더워요/추워요? (더워요/추워요): \")\nplace = input(\"학교/놀이터? (학교/놀이터): \")\n\nif temp == \"더워요\" and place == \"학교\":\n    print(\"추천: 반팔 + 얇은 셔츠\")\nelif temp == \"더워요\" and place == \"놀이터\":\n    print(\"추천: 반팔 + 반바지 + 모자\")\nelif temp == \"추워요\" and place == \"학교\":\n    print(\"추천: 니트 + 코트\")\nelse:\n    print(\"추천: 패딩 + 목도리\")"},{"title":"기록","note":"설계 5칸 종이에 내 주제의 질문·추천·갈래를 적고 사진으로 남기세요. 2회차에 이 종이로 이어 갑니다."}],"out":"=== 오늘 뭐 입지? ===\n더워요/추워요? (더워요/추워요): 더워요\n학교/놀이터? (학교/놀이터): 놀이터\n추천: 반팔 + 반바지 + 모자"}],"practice":[{"title":"실습 1 — 경우의 수 세기","prompt":"질문이 1개, 2개, 3개일 때 갈래가 몇 개인지 적고, 3개일 때 왜 많은지 한 줄로 쓰세요.","expect":"1개 → 2갈래 / 2개 → 4갈래 / 3개 → 8갈래. 3개는 if를 8번 써야 해서 많다."},{"title":"실습 2 — 4갈래 표 채우기","prompt":"아래 표의 빈칸을 채우고, 각 칸에 들어갈 추천을 정하세요.","starter":"(밥, yes) = ?\n(밥, no)  = ?\n(면, yes) = ?\n(면, no)  = ?","expect":"(밥, yes) 제육덮밥 / (밥, no) 카레 / (면, yes) 짬뽕 / (면, no) 잔치국수"},{"title":"실습 3 — 이상한 입력 넣어 보기","prompt":"kind에 \"rice\", \"ㅂ\", 빈칸을 넣어 보세요. 오늘은 무엇이 나오면 될까요?","expect":"어떤 값을 넣어도 마지막 else의 추천(잔치국수)이 나온다 — 2회차에 안내 문구로 고칩니다."},{"title":"실습 4 — 내 주제 질문 2개 정하기","prompt":"내 추천기의 질문 2개와 답 4개를 적으세요. 질문은 예/아니오보다 두 갈래로 나뉘는 것이 좋습니다.","expect":"예) (실내/실외) × (혼자/같이) → 4가지 활동 추천"}],"mistakes":[{"symptom":"어떤 답을 넣어도 마지막 추천만 나온다","cause":"and 대신 쉼표를 썼거나 비교를 = 로 했다"},{"symptom":"SyntaxError","cause":"if kind == 밥 — 따옴표 누락"},{"symptom":"4갈래인데 2개만 나온다","cause":"경우의 수를 덜 셈 (2 × 2 = 4 확인)"},{"symptom":"질문은 나오는데 결과가 없다","cause":"if 블록이 없거나 print 누락"}],"hints":["질문 2개면 갈래는 4개예요. 표를 그려 보세요.","조건을 소리 내어 두 번 읽어 보세요.","비교는 ==, 글자는 따옴표로 감싸요.","어떤 답에도 같은 결과면 and 조건이 겹쳤는지 보세요."],"selfcheck":["4가지 답 조합을 모두 넣어 봤다","내 주제로 1번 이상 바꿨다","설계 5칸 종이를 채웠다(버리지 말고 보관)","내 추천기의 질문 2개를 말로 설명할 수 있다"],"note":"추천기에 전화번호·주소는 필요 없어요. 개인정보는 넣지 않습니다."}$jc$::jsonb, $jt${"demo":"'오늘은 새로 배우는 게 없습니다. 처음으로 프로그램 하나를 통째로 만듭니다. 질문 2개로 4가지 추천이 나오는 오늘 뭐 먹지? — 이게 끝나면 내가 만든 프로그램이 하나 생깁니다. 오늘의 절반은 코딩이 아니라 설계입니다.'","analogy":"경우의 수를 세는 게 설계 — 질문 1개 = 갈래 2개, 2개 = 4개. 3개면 8갈래라 너무 많다는 걸 직접 세게 하면 범위 조절을 스스로 합니다. 설계 5칸은 요리 전에 재료를 놓아 두는 것.","timeline":[{"min":"0~10","title":"도입 — 오늘은 작품 하나","detail":"완성 추천기를 먼저 시연. \"오늘 두 시간 뒤 이게 여러분 것이 됩니다\" + 4주 블록 마지막이라는 것(발표 있는 날)을 예고."},{"min":"10~30","title":"설계 5칸 (종이)","detail":"질문/저장/갈래/출력/빼기(개인정보). 15분은 코드 없이 종이만. 3~4명 발표해서 서로 주제를 말로 설명하게 합니다."},{"min":"30~55","title":"골격 따라 만들기","detail":"밥/면 추천기를 그대로 따라 치며 구조를 몸에 익힘. 4갈래 표를 종이에 채우고 코드와 1:1로 맞추기."},{"min":"55~85","title":"내 주제로 바꾸기","detail":"질문 2개·추천 4개를 내 것으로. 막히는 학생은 밥/면에서 단어만 바꾸게 하면 됩니다. 여기까지가 오늘의 필수."},{"min":"85~100","title":"4갈래 전수 테스트","detail":"네 조합을 모두 넣어 보는 표를 만들게 합니다. 하나라도 다르면 조건 순서/철자 문제."},{"min":"100~112","title":"미니 실습 3·4 + AI","detail":"이상한 입력을 넣어 보게 하고(2회차 예고), AI에게는 주제·문구 후보만 받습니다."},{"min":"112~118","title":"저장·설계 종이 보관","detail":"파일 저장 + 설계 종이에 이름을 쓰고 걷어서 보관. 2회차에 이 종이가 없으면 처음부터 다시 짜게 됩니다."},{"min":"118~120","title":"예고","detail":"다음 시간은 완성 + 이상한 입력 막기 + 1분 발표. \"발표에서 아직 아쉬운 점을 말할 수 있으면 진짜 이해한 것.\""}],"board":[{"say":"오늘 목표는 한 프로그램","write":"빈 화면에 완성 화면 먼저"},{"say":"설계 5칸","write":"질문/저장/갈래/출력/빼기"},{"say":"경우의 수","write":"2 × 2 = 4, 3개면 8"},{"say":"and로 묶기","write":"kind == \"밥\" and spicy == \"yes\""},{"say":"마지막은 else","write":"else는 남은 전부"},{"say":"4갈래 표","write":"(밥,yes) (밥,no) (면,yes) (면,no)"},{"say":"함정","write":"어떤 답에도 마지막만 나오는 코드 즉석 시연"},{"say":"개인정보","write":"\"추천기에 전화번호는 필요 없다\" 한 줄"}],"ai":[{"when":"주제 고를 때 15분","what":"주제 후보 3개만 받기","prompt":"중학생이 만드는 파이썬 추천기 주제 3개만 제안해줘. 코드는 절대 쓰지 마.","rule":"고르는 건 나 / AI가 쓴 코드 붙이기 금지 / 설명 못 하는 줄은 지운다"},{"when":"100분","what":"조합 빠진 곳 점검","prompt":"내 추천기 질문: (실내/실외) × (혼자/같이). 이 조합에서 내가 빠뜨렸을 수 있는 경우만 알려줘.","rule":"코드가 아니라 경우만"}],"errors":[{"symptom":"어떤 답이든 마지막만","cause":"and 대신 쉼표 / = 비교","coach":"조건을 소리 내어 두 번 읽어 보기."},{"symptom":"NameError","cause":"변수 이름 다름","coach":"변수 표에 적힌 이름 그대로."},{"symptom":"첫 줄만 실행되고 끝","cause":"들여쓰기 위치","coach":"if 블록 안/밖 구분."},{"symptom":"설계를 못 함","cause":"주제가 너무 큼","coach":"질문 2개로 줄이게. 8갈래는 2회차 심화."},{"symptom":"4갈래 중 2개만","cause":"조건 중복","coach":"조합 표와 코드 if를 줄로 맞춰 보게."}],"qa":[{"q":"주제를 못 정하겠어요","a":"좋아하는 것 3개를 말하게 하고, 그중 질문 2개로 나눌 수 있는 것을 고르게 합니다. AI 후보 3개도 활용."},{"q":"질문을 3개 하고 싶어요","a":"8갈래가 됩니다. 오늘은 2개로 완성하고, 3개는 2회차 심화로 남겨 둡니다."},{"q":"추천이 4개나 필요한가요?","a":"네 조합이 모두 다른 결과를 내야 프로그램이 살아 있습니다. 4개가 최소입니다."},{"q":"친구 코드를 봐도 되나요?","a":"구조(질문 · 갈래 수)만 보게 하고, 문장은 자기 것으로 쓰게 합니다."},{"q":"개인정보를 왜 빼요?","a":"추천에 필요 없는 정보는 받지 않는 습관. 전화번호·주소·학교 이름은 넣지 않습니다."}],"tips":["설계 종이는 반드시 걷어서 보관합니다. 2회차에 이 종이가 없으면 처음부터 다시 짜게 됩니다.","30분 설계에서 코드를 먼저 잡는 학생은 \"질문 2개가 뭐예요?\"로 되돌립니다.","85분 4갈래 전수 테스트가 이 수업의 평가입니다. 네 조합을 다 넣어 본 학생은 2회차가 편합니다."]}$jt$::jsonb,
   'print("=== 오늘 뭐 먹지? ===")

kind = input("밥/면 중에 뭐가 당겨요? (밥/면): ")
spicy = input("매운 거 좋아해요? (yes/no): ")

if kind == "밥" and spicy == "yes":
    print("추천: 제육덮밥 🔥")
elif kind == "밥" and spicy == "no":
    print("추천: 카레라이스")
elif kind == "면" and spicy == "yes":
    print("추천: 짬뽕 🔥")
elif kind == "면" and spicy == "no":
    print("추천: 잔치국수")
else:
    print("''밥'' 또는 ''면''으로 다시 입력해 주세요.")', '주제가 안 정해지면 "파이썬 추천기 주제 3개만, 코드는 쓰지 마"라고 묻고 내가 하나 골라요.', null,
   'python', true, 10),
  ('py-w04-s2', 'theory', '4주 2회차 — 추천기 완성·업그레이드·발표 (2시간)', 'python', 4, 2,
   '이상한 입력을 막고, 예산 기능을 붙여 1분 발표까지 합니다. 4주 블록의 마무리.', $jc${"goal":"4갈래가 모두 다르게 나오고, 이상한 입력에는 안내 문구가 나오며, 1분 발표를 한다","preview":"=== 오늘 뭐 먹지? ===\n밥/면 중에 뭐가 당겨요? (밥/면): 면\n매운 거 좋아해요? (yes/no): yes\n예산(원): 8000\n추천: 짬뽕 🔥\n든든하게 먹고 와요","words":["이상한 입력","안내 문구","발표"],"conceptTitle":"이상한 입력은 손님이 문을 잘못 연 것","concept":[{"code":"kind == \"밥\"","mean":"정확히 \"밥\"일 때만"},{"code":"else:","mean":"\"밥\"도 \"면\"도 아니면 안내 문구"},{"code":"pick = \"\"","mean":"추천이 없었다는 표시로 빈 글자를 넣어 둔다"},{"code":"if pick == \"\":","mean":"추천이 비었는지 마지막에 확인"},{"code":"반복은 5주에","mean":"다시 물어보는 기능은 5주 반복문에서 배웁니다 — 오늘은 안내 문구까지만"}],"predict":{"code":"kind = \"rice\"\nif kind == \"밥\":\n    print(\"제육\")\nelif kind == \"면\":\n    print(\"짬뽕\")\nelse:\n    print(\"밥 또는 면으로 입력해 주세요\")","answer":"밥 또는 면으로 입력해 주세요 — else가 받아 줍니다"},"steps":[{"title":"오늘 할 일","note":"① 4갈래 다 나오게 완성 ② 이상한 입력 넣어 보기(ㅂ, rice, 빈칸) ③ 업그레이드 + 1분 발표"},{"title":"이상한 입력 막기","code":"if kind == \"밥\":\n    ...\nelif kind == \"면\":\n    ...\nelse:\n    print(\"'밥' 또는 '면'으로 다시 입력해 주세요.\")"},{"title":"추천과 가격을 변수에 담기","code":"pick = \"짬뽕\"\nprice = 9000\n\nif budget < price:\n    print(f\"예산이 {price - budget}원 부족해요\")"},{"title":"1분 발표 3문장","note":"① 이 프로그램은 ___을 물어보고 ___을 추천합니다. ② 제가 고친 건 ___입니다. ③ 아직 아쉬운 점은 ___입니다."}],"debug":[{"kind":"문법","title":"문제 A — 쉼표로 조건을 이은 코드","code":"kind = input(\"밥/면: \")\nspicy = input(\"매운 거? (yes/no): \")\n\nif kind == \"밥\", spicy == \"yes\":\n    print(\"제육덮밥\")\nelse:\n    print(\"카레\")","symptom":"SyntaxError: invalid syntax (if 줄)","check":"밥과 yes를 넣으면 제육덮밥, 밥과 no를 넣으면 다른 결과가 나온다.","hint":"두 조건을 동시에 만족하려면 and를 씁니다. 쉼표는 조건문에서 쓰지 않습니다."},{"kind":"실행","title":"문제 B — 예산 비교가 안 되는 코드","code":"budget = input(\"예산(원): \")\nprice = 9000\n\nif budget < price:\n    print(\"예산이 부족해요\")\nelse:\n    print(\"주문 가능\")","symptom":"TypeError: '<' not supported between instances of 'str' and 'int'","check":"예산 8000을 넣으면 \"예산이 부족해요\"가 나온다.","hint":"input은 글자를 줍니다. int(input(...))로 숫자로 바꾸세요."},{"kind":"논리","title":"문제 C — 어떤 답에도 같은 추천","code":"kind = input(\"밥/면: \")\nspicy = input(\"매운 거? (yes/no): \")\n\nif kind == \"밥\":\n    print(\"추천: 제육덮밥\")\nelif kind == \"밥\":\n    print(\"추천: 카레라이스\")\nelif kind == \"면\":\n    print(\"추천: 짬뽕\")\nelse:\n    print(\"추천: 잔치국수\")","symptom":"밥+no를 넣어도 제육덮밥이 나온다. 카레라이스는 영원히 안 나온다.","check":"밥+yes 제육, 밥+no 카레, 면+yes 짬뽕, 면+no 잔치국수","hint":"같은 조건이 두 번 있습니다. 두 번째는 영원히 실행되지 않습니다. spicy 조건을 넣어 네 갈래를 만드세요."}],"practice":[{"title":"확인 1 — 이상한 입력 3개","prompt":"완성한 코드에 ㅂ / rice / 빈칸을 넣고 어떤 문구가 나오는지 적으세요.","expect":"세 경우 모두 \"밥 또는 면으로 다시 입력해 주세요.\""},{"title":"확인 2 — 예산 계산","prompt":"추천 가격 9000원, 예산 8000원일 때 부족한 금액을 출력하세요.","starter":"price = 9000\nbudget = 8000\n# 부족한 금액을 계산해 출력","expect":"1000원 부족해요","hint":"{price - budget}"}],"mistakes":[{"symptom":"4갈래 중 2개만 나온다","cause":"and 조건이 중복되거나 빠졌다"},{"symptom":"예산 추가 후 다 안 나온다","cause":"int() 누락"},{"symptom":"빈칸 입력 시 멈춘다","cause":"int(\"\") 에서 ValueError — 지금 단계에선 정상"},{"symptom":"안내 문구가 안 나온다","cause":"else가 없거나 마지막 elif가 else 역할을 함"}],"hints":["조합 표(밥·매움 / 밥·안매움 / 면·매움 / 면·안매움)를 채워 보세요.","이상한 입력 3개를 직접 넣어 보세요.","발표는 내 코드를 한 줄씩 읽으며 \"이 줄은 ~한다\"를 적으면 됩니다.","마지막 else가 안내 문구 담당이에요."],"selfcheck":["4가지 조합이 모두 다른 결과를 낸다","이상한 입력에 안내 문구가 나온다","미션 1개 이상 붙였다","4주_추천기_내이름.py 로 저장했다","1분 발표 3문장을 말할 수 있다"],"missions":{"basic":"추천마다 이유 한 줄 붙이기 — print(\"추천: 카레라이스 — 안 맵고 든든해요\")","challenge":"예산을 물어 부족하면 \"예산이 N원 부족해요\", 6000원 미만이면 \"가성비\", 이상이면 \"든든\" 문구 바꾸기","deep":"질문 3개(8갈래)로 늘리기 + 친구 추천기를 실행해 보고 이상한 점 1개 적기"},"missionsOut":{"basic":"추천: 카레라이스 — 안 맵고 든든해요","challenge":"예산(원): 8000\n추천: 짬뽕 🔥\n예산이 1000원 부족해요. 다른 메뉴를 골라 볼까요?","deep":"질문 3개 → 8갈래 표가 채워지고, 친구 코드에서 \"빈칸 입력 시 안내 없음\"을 발견"}}$jc$::jsonb, $jt${"demo":"'오늘로 4주가 끝납니다. 완성 + 발표예요. 발표에서 아직 아쉬운 점을 말할 수 있으면 그게 진짜 이해한 겁니다. 오늘 두 시간은 완성 60분, 업그레이드 30분, 발표 20분으로 갑니다.'","analogy":"손님(사용자)은 뭐든 칩니다. 프로그램이 안내판을 세워 두면 무너지지 않습니다. 다시 물어보는 문은 5주 반복문에서 만듭니다 — 오늘은 \"안내판\"까지만.","timeline":[{"min":"0~10","title":"도입 — 오늘의 순서","detail":"완성 60 / 업그레이드 30 / 발표 20을 칠판에. 설계 종이를 나눠 주고 지난 시간 파일을 열게 합니다."},{"min":"10~30","title":"디버깅 A·B·C","detail":"A(쉼표 문법)·B(예산 int 누락, 오늘 새로 붙인 부분)·C(중복 조건). C는 4갈래 표와 코드를 나란히 놓고 없어진 갈래를 찾게."},{"min":"30~60","title":"완성 — 4갈래 전수 테스트","detail":"네 조합을 표에 적고 실행 결과를 적게 합니다. 통과 못 한 학생은 여기서 잡습니다. 통과한 학생은 이상한 입력 실험."},{"min":"60~75","title":"이상한 입력 막기","detail":"ㅂ / rice / 빈칸. else 안내 문구를 넣고 세 번 확인. int 빈칸 ValueError는 \"지금은 정상\"으로 설명."},{"min":"75~100","title":"업그레이드 미션","detail":"기본(이유 한 줄) → 도전(예산 3단) → 심화(8갈래). 도전까지가 대부분의 목표. 예시 출력과 비교하게."},{"min":"100~112","title":"발표 준비 + AI","detail":"3문장 틀을 채우게 하고, AI에게는 \"어색한 부분만 2군데\"만 받습니다. AI 문장을 그대로 읽지 않게."},{"min":"112~120","title":"1분 발표 + 4주 마무리","detail":"한 명 1분, 칭찬 1 + 질문 1. 발표 후 4주 동안 배운 것 3개를 손으로 꼽게 하고 5주 for 예고."}],"board":[{"say":"오늘의 시간표","write":"완성 60 / 업그레이드 30 / 발표 20"},{"say":"설계 종이 꺼내기","write":"5칸 표 옆에 체크"},{"say":"4갈래 전수 테스트","write":"조합 표 + 실행 결과 4줄"},{"say":"이상한 입력 3개","write":"ㅂ / rice / 빈칸 → 안내 문구"},{"say":"예산 3단","write":"부족 / 6000 미만 / 이상"},{"say":"미션 선택","write":"기본/도전/심화 + 예시 출력"},{"say":"발표 3문장","write":"무엇을 / 고친 것 / 아쉬운 점"},{"say":"5주 예고","write":"같은 질문을 5번 하려면? → 반복문"}],"ai":[{"when":"발표 준비 105분","what":"발표 3문장 다듬기","prompt":"내 발표문: '이 프로그램은 밥이랑 면 물어보고 추천해요. 제가 고친 건...' 어색한 부분만 2군데 짚어줘. 새로 쓰지 마.","rule":"AI가 쓴 문장을 그대로 읽기 금지 — 내 말로 다시"},{"when":"80분","what":"업그레이드 후보 3개","prompt":"내 메뉴 추천기에 붙일 기능 3개만 제안해줘. 코드는 쓰지 마.","rule":"고르는 건 학생"}],"errors":[{"symptom":"4갈래 중 2개만","cause":"and 조건 중복·누락","coach":"조합 표를 채우게."},{"symptom":"빈칸에서 멈춤","cause":"int(\"\") ValueError","coach":"지금 단계에선 정상 — 안내 문구로 처리."},{"symptom":"발표를 못 함","cause":"자기 코드를 안 읽어 봄","coach":"한 줄씩 읽으며 \"이 줄은 ~한다\"를 적게."},{"symptom":"예산 비교가 항상 참/거짓","cause":"int 누락 또는 문자열 비교","coach":"타입을 확인. 3주 B와 같은 실수."},{"symptom":"else가 안내를 안 함","cause":"else가 없음","coach":"마지막 갈래를 else로 바꾸게."}],"qa":[{"q":"친구는 8갈래인데 저는 4갈래예요","a":"4갈래 완성이 먼저입니다. 심화는 시간이 남을 때만. 완성도가 우선."},{"q":"빈칸을 넣으면 프로그램이 죽어요","a":"int(\"\")에서 나는 ValueError입니다. 지금은 정상 — if로 막는 건 13주. 오늘은 안내 문구만."},{"q":"발표에서 뭘 말해야 해요?","a":"3문장 틀: 무엇을 물어보고 무엇을 추천하는지 / 내가 고친 것 / 아직 아쉬운 점."},{"q":"예산을 넣으면 추천이 안 나와요","a":"if/elif가 끝난 뒤 print가 예산 if 안으로 들어갔는지 확인. 들여쓰기를 보게 하세요."},{"q":"다음 주엔 뭐 해요?","a":"for 반복문. 같은 질문을 5번 하는 추천기로 확장합니다."}],"tips":["8갈래(심화)는 욕심내지 않게 — 4갈래 완성이 우선입니다.","발표는 칭찬 1 + 질문 1로 짧게. \"왜 이 메뉴를 추천하게 했어요?\"가 설계 설명이 됩니다.","4주 블록 마지막이므로 파일 이름 규칙(4주_추천기_이름.py)을 꼭 확인해 두면 나중에 포트폴리오가 됩니다."]}$jt$::jsonb,
   'print("=== 오늘 뭐 먹지? ===")

kind = input("밥/면 중에 뭐가 당겨요? (밥/면): ")
spicy = input("매운 거 좋아해요? (yes/no): ")
budget = int(input("예산(원): "))

if kind == "밥" and spicy == "yes":
    pick = "제육덮밥 🔥"
    price = 8000
elif kind == "밥" and spicy == "no":
    pick = "카레라이스"
    price = 7000
elif kind == "면" and spicy == "yes":
    pick = "짬뽕 🔥"
    price = 9000
elif kind == "면" and spicy == "no":
    pick = "잔치국수"
    price = 6000
else:
    pick = ""
    price = 0

if pick == "":
    print("''밥'' 또는 ''면''으로 다시 입력해 주세요.")
else:
    print(f"추천: {pick}")
    if budget < price:
        print(f"예산이 {price - budget}원 부족해요. 다른 메뉴를 골라 볼까요?")
    elif budget < 6000:
        print("가성비 좋은 선택이에요")
    else:
        print("든든하게 먹고 와요")', '발표 전에 "내 발표문에서 어색한 부분만 2군데"라고 물어보세요. 새로 써 달라고 하지 않기!', null,
